const panels=[['trex-iptv','Trex IPTV','trex-iptv.png','Sports-ready IPTV panel'],['8k-strong','8K Strong','8k-strong.webp','4K-focused reseller panel'],['ultra-8k-ott','Ultra 8K OTT','ultra-8k-ott.png','Premium OTT streaming route'],['dino-iptv','Dino IPTV','dino-iptv.png','Flexible IPTV reseller option'],['lion-ott','Lion OTT','lion-ott.png','Sports and entertainment panel'],['nexon-iptv','Nexon IPTV','nexon-iptv.png','IPTV catalog and reseller route'],['tivione','TiviOne','tivione.png','European customer plans'],['eagle-iptv','Eagle IPTV','eagle-iptv.png','Fast IPTV panel access'],['mega-ott','Mega OTT','mega-ott.png','Managed OTT provider option'],['crystal-ott','Crystal OTT','crystal-ott.png','Direct support OTT panel'],['magnum-golden-ott','Magnum / Golden OTT','magnum-golden-ott.png','B2B reseller panel'],['infinity-iptv','Infinity IPTV','infinity-iptv.png','IPTV plans and credits'],['max-ott','Max OTT','max-ott.png','Long-term OTT options'],['dream-4k-iptv','Dream 4K / Dream 24K','dream-4k-iptv.png','4K-ready IPTV package'],['promax-4k-ott','ProMax 4K OTT','promax-4k-ott.png','Professional 4K OTT panel']];
document.querySelector('#panel-grid').innerHTML=panels.map(([slug,name,logo,label],index)=>`<article class="panel-card"><span class="number">${String(index+1).padStart(2,'0')}</span><div class="logo"><img src="/assets/logos/${logo}" alt="${name} logo"></div><p class="type">${label}</p><h4>${name}</h4><p class="description">Explore subscription plans, reseller credits and dedicated setup support for this IPTV / OTT panel.</p><a href="/${slug}/">Open ${name} <b>→</b></a></article>`).join('');
const menu=document.querySelector('.menu'),nav=document.querySelector('#site-nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});
